#ifndef INKTAG_NRF_DFU_CRYPTO_H
#define INKTAG_NRF_DFU_CRYPTO_H

#include <stdbool.h>
#include <stdint.h>

bool inktag_nrf_dfu_sha256_matches_le(uint8_t const expected[32],
                                      uint8_t const *data,
                                      uint32_t length);
/* public_key must be 32-bit aligned, as generated by nrfutil's
 * __ALIGN(4) dfu_public_key.c. signature need not be aligned. */
bool inktag_nrf_dfu_p256_verify_le(uint8_t const public_key[64],
                                   uint8_t const signature[64],
                                   uint8_t const *data,
                                   uint32_t length);

#endif
